# PTX source for mean reduction over dimension 1 (size dim1) on fp16 tensors.
PTX_SOURCE = r"""
.version 7.0
.target sm_80
.address_size 64

.visible .entry mean_reduce_fp16(
    .param .u64   in_ptr,
    .param .u64   out_ptr,
    .param .u32   batch,
    .param .u32   dim1,
    .param .u32   dim2
)
{
    // Thread identifiers
    .reg .u32   %tid.x;
    .reg .u32   %blockdim.x;
    .reg .u32   %blockidx.x;
    .reg .u64   %thread_id;
    .reg .u64   %global_thread_id;

    ld.param.u32    %tid.x,        [tid.x];
    ld.param.u32    %blockdim.x,   [blockdim.x];
    ld.param.u32    %blockidx.x,   [blockidx.x];

    // global_thread_id = blockIdx.x * blockDim.x + threadIdx.x
    mul.lo.u32      %blockidx.x, %blockidx.x, %blockdim.x;
    add.u32         %tid.x, %blockidx.x, %tid.x;
    cvt.u64.u32     %global_thread_id, %tid.x;

    // Load problem sizes
    .reg .u32   %batch;
    .reg .u32   %dim1;
    .reg .u32   %dim2;
    ld.param.u32    %batch, [batch];
    ld.param.u32    %dim1,  [dim1];
    ld.param.u32    %dim2,  [dim2];

    // Compute total number of output elements = batch * dim2
    .reg .u64   %out_elems;
    cvt.u64.u32    %out_elems, %batch;
    mul.lo.u64     %out_elems, %out_elems, %dim2;

    // if (global_thread_id >= out_elems) return;
    setp.ge.u64    %p0, %global_thread_id, %out_elems;
    @%p0          ret;

    // Derive output coordinates:
    // out_index = batch_idx * dim2 + col_idx
    .reg .u64   %batch_idx;
    .reg .u64   %col_idx;
    .reg .u64   %tmp;

    // batch_idx = global_thread_id / dim2
    cvt.u64.u32    %tmp, %dim2;
    div.u64        %batch_idx, %global_thread_id, %tmp;
    // col_idx = global_thread_id % dim2
    mul.lo.u64     %tmp, %batch_idx, %tmp;
    sub.u64        %col_idx, %global_thread_id, %tmp;

    // Pointers
    .reg .u64   %in_ptr;
    .reg .u64   %out_ptr;
    ld.param.u64 %in_ptr,  [in_ptr];
    ld.param.u64 %out_ptr, [out_ptr];

    // Accumulator in fp32
    .reg .f32   %sum_f32;
    mov.f32     %sum_f32, 0f00000000; // 0.0f

    // Loop over reduction dimension dim1
    .reg .u32   %k;
    mov.u32     %k, 0;

$loop:
    // Compute linear index of input element:
    // idx = ((batch_idx * dim1) + k) * dim2 + col_idx
    .reg .u64   %idx;
    .reg .u64   %temp64;
    cvt.u64.u32    %temp64, %dim1;
    mul.lo.u64     %temp64, %batch_idx, %temp64;   // batch_idx * dim1
    cvt.u64.u32    %temp64, %k;
    add.u64        %temp64, %temp64, %temp64; // Actually we need to add k to previous product
    // Wait: we need ((batch_idx * dim1) + k)
    // Let's compute product then add k:
    // product = batch_idx * dim1
    mul.lo.u64     %temp64, %batch_idx, %dim1;   // batch_idx * dim1
    cvt.u64.u32    %idx, %k;
    add.u64        %temp64, %temp64, %idx;       // (batch_idx*dim1)+k
    // Multiply by dim2
    cvt.u64.u32    %idx, %dim2;
    mul.lo.u64     %temp64, %temp64, %idx;       // ((batch_idx*dim1)+k)*dim2
    // Add col_idx
    add.u64        %idx, %temp64, %col_idx;      // final linear index

    // Byte offset = idx * 2 (since fp16)
    .reg .u64   %byte_offset;
    shl.b64     %byte_offset, %idx, 1;

    // Load half (fp16)
    .reg .f16   %val_f16;
    ld.global.f16 %val_f16, [%in_ptr + %byte_offset];

    // Convert to fp32 and accumulate
    .reg .f32   %val_f32;
    cvt.f32.f16 %val_f32, %val_f16;
    add.f32    %sum_f32, %sum_f32, %val_f32;

    // Increment k
    add.u32    %k, %k, 1;
    setp.lt.u32 %p1, %k, %dim1;
    @%p1 bra $loop;

    // Compute mean = sum / dim1
    .reg .f32   %dim1_f32;
    cvt.f32.u32 %dim1_f32, %dim1;
    div.f32    %sum_f32, %sum_f32, %dim1_f32;

    // Convert back to fp16
    .reg .f16   %out_f16;
    cvt.f16.f32 %out_f16, %sum_f32;

    // Store result
    // output linear index = global_thread_id
    shl.b64    %byte_offset, %global_thread_id, 1; // *2
    st.global.f16 [%out_ptr + %byte_offset], %out_f16;

    ret;
}
"""

class ModelNew:
    def __init__(self, dim: int):
        self.dim = dim
        # Load the PTX module using the harness API
        self.module = ptx_load(PTX_SOURCE)

    def __call__(self, x: torch.Tensor) -> torch.Tensor:
        assert x.is_cuda and x.dtype == torch.float16, "Input must be CUDA fp16 tensor"
        # Input shape expected: (batch, dim1, dim2)
        batch, dim1, dim2 = x.shape
        # Reduction over dim=1 (as per init)
        out = torch.empty((batch, dim2), dtype=torch.float16, device=x.device)

        # Launch parameters
        total_out = batch * dim2
        threads_per_block = 256
        blocks = (total_out + threads_per_block - 1) // threads_per_block

        # Arguments must be passed as Python integers (converted to appropriate PTX types)
        args = [
            x.data_ptr(),            # in_ptr (u64)
            out.data_ptr(),          # out_ptr (u64)
            int(batch),              # batch (u32)
            int(dim1),               # dim1 (u32) – reduction dimension size
            int(dim2)                # dim2 (u32)
        ]

        # Launch the kernel
        ptx_launch(
            self.module,
            "mean_reduce_fp16",
            (blocks, 1, 1),            # grid
            (threads_per_block, 1, 1), # block
            args
        )
        return out
